int binary_search(std::vector<int>& a, int target) {
    int left = 0;
    int right = a.size() - 1;
    while (left <= right) {
        int mid = (right + left) / 2;
        if (a[mid] == target) {
            return mid;
        } else if (a[mid] < target) {
            left = mid + 1;
        } else {
            right = mid - 1;
        }
    }
    return -1;
}

