fn binary_search(a: &[i32], target: i32) -> i32 {
    let mut left: usize = 0;
    if a.is_empty() return -1;
    let mut right: usize = a.len() - 1;
    while left <= right {
        let mid = (left + right) / 2;
        if a[mid] == target {
            return mid as i32;
        } else if a[mid] < target {
            left = mid + 1;
        } else {
            if mid == 0 {
                break;
            }
            right = mid - 1;
        }
    }
    -1
}
